import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:intl/intl.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/care_entities.dart';import 'record_editor_screen.dart';
class RecordsScreen extends ConsumerWidget{const RecordsScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final c=ref.watch(appControllerProvider),pet=c.selectedPet;final records=pet==null?<PetRecord>[]:c.items('pet_records').map(PetRecord.fromMap).where((e)=>e.petId==pet.id).toList()..sort((a,b)=>b.eventDate.compareTo(a.eventDate));return Scaffold(appBar:AppBar(title:const Text('Health record organizer'),actions:[IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const RecordEditorScreen())),icon:const Icon(Icons.add))]),body:records.isEmpty?const Center(child:Text('No records saved for this pet.')):ListView(padding:const EdgeInsets.all(16),children:records.map((e)=>Card(child:ListTile(leading:const Icon(Icons.folder_copy_outlined,color:Color(0xFF39845A)),title:Text(e.title),subtitle:Text('${e.type} · ${DateFormat.yMMMd().format(e.eventDate)} · Entered by you\n${e.clinic}')))).toList()));}}
